html,body{margin:0;height:100%;background:#0f172a;font-family:'Open Sans',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#e2e8f0;}
*{box-sizing:border-box;}
.wrap{height:calc(var(--appsmith-ui-height)*1px);overflow:hidden;padding:18px 22px;display:flex;flex-direction:column;}
.filter{margin-bottom:16px;flex:0 0 auto;}
.filter label{display:block;font-size:13px;color:#60a5fa;font-weight:600;margin-bottom:6px;}
.filter select{background:#1e293b;color:#fff;border:1px solid #334155;border-radius:6px;padding:8px 12px;font-size:14px;min-width:220px;outline:none;cursor:pointer;}
.filter select:focus{border-color:#3b82f6;}
.tblwrap{flex:1 1 auto;min-height:0;border:1px solid #1e293b;border-radius:8px;overflow:auto;}
table{border-collapse:separate;border-spacing:0;font-size:14px;white-space:nowrap;}
thead th{position:sticky;top:0;background:#0f172a;color:#cbd5e1;font-weight:700;text-align:right;padding:13px 18px;border-bottom:2px solid #1e293b;z-index:2;}
th.attr,td.attr{position:sticky;left:0;text-align:left;background:#0f172a;z-index:1;border-right:2px solid #1e293b;color:#f1f5f9;font-weight:600;}
thead th.attr{z-index:3;}
tbody td{padding:12px 18px;text-align:right;color:#e2e8f0;}
tbody tr:nth-child(odd) td{background:#1e293b;} tbody tr:nth-child(odd) td.attr{background:#16233b;}
tbody tr:nth-child(even) td{background:#0f172a;} tbody tr:nth-child(even) td.attr{background:#0f172a;}
.empty{padding:44px 20px;text-align:center;color:#94a3b8;}
.empty .big{font-size:15px;color:#cbd5e1;margin-bottom:6px;} .empty .sm{font-size:13px;color:#64748b;}
::-webkit-scrollbar{width:10px;height:10px;background:#0f172a;} ::-webkit-scrollbar-thumb{background:#1e293b;border-radius:4px;border:2px solid #0f172a;}

