function esc(s){return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}
var selAttr="ALL";
function render(){
  var m=appsmith.model||{}; var all=m.rows||[];
  var attrSet={}; all.forEach(function(r){ if(r.Attribute) attrSet[r.Attribute]=true; });
  var attrsAll=Object.keys(attrSet).sort();
  if(selAttr!=="ALL" && attrsAll.indexOf(selAttr)<0) selAttr="ALL";

  // month columns ordered by underlying date, most recent first
  var monthSort={};
  all.forEach(function(r){ var k=r.Month; if(k){ var s=String(r._sort||""); if(!monthSort[k]||s>monthSort[k]) monthSort[k]=s; }});
  var months=Object.keys(monthSort).sort(function(a,b){ return monthSort[b].localeCompare(monthSort[a]); });

  // value map[attribute][month]
  var map={};
  all.forEach(function(r){ if(!map[r.Attribute]) map[r.Attribute]={}; map[r.Attribute][r.Month]=r.Value; });

  var attrs = (selAttr==="ALL") ? attrsAll : [selAttr];

  var opts='<option value="ALL"'+(selAttr==="ALL"?" selected":"")+'>All Attributes</option>'
    + attrsAll.map(function(a){ return '<option value="'+esc(a)+'"'+(selAttr===a?" selected":"")+'>'+esc(a)+'</option>'; }).join('');
  var html='<div class="filter"><label>Attribute</label><select id="attrSel">'+opts+'</select></div>';

  if(m.isLoading){ html+='<div class="empty"><div class="big">Loading…</div></div>'; }
  else if(!attrsAll.length || !months.length){
    html+='<div class="empty"><div class="big">The Location needs to have Attributes in order to allow for Production Data values to be entered.</div><div class="sm">No monthly attribute data for this location.</div></div>';
  } else {
    html+='<div class="tblwrap"><table><thead><tr><th class="attr">Attribute</th>';
    months.forEach(function(mo){ html+='<th>'+esc(mo)+'</th>'; });
    html+='</tr></thead><tbody>';
    attrs.forEach(function(a){
      html+='<tr><td class="attr">'+esc(a)+'</td>';
      months.forEach(function(mo){ var v=(map[a]||{})[mo]; html+='<td>'+((v==null||v==="")?"-":esc(v))+'</td>'; });
      html+='</tr>';
    });
    html+='</tbody></table></div>';
  }
  var root=document.getElementById("root"); if(!root) return;
  root.innerHTML='<div class="wrap">'+html+'</div>';
  var sel=document.getElementById("attrSel");
  if(sel) sel.onchange=function(e){ selAttr=e.target.value; render(); };
}
appsmith.onReady(function(){ render(); appsmith.onModelChange(render); });

